mapper.select:
select from mall_product p left join mall_category c on c.id = p.category_id left join mall_brand b on b.id = p.brand_id
and ( p.name like concat('%', #{keyword}, '%') or p.subtitle like concat('%', #{keyword}, '%') or b.name like concat('%', #{keyword}, '%') or c.name like concat('%', #{keyword}, '%') )
and p.name like concat('%', #{name}, '%')
and p.category_id in
#{cid}
and p.brand_id = #{brandId}
and p.price_high >= #{minPrice}
and p.price_low <= #{maxPrice}
and p.status = #{status}
order by p.price_low asc, p.id desc order by p.price_low desc, p.id desc order by p.sales desc, p.id desc order by p.rating desc, p.id desc order by p.create_time desc, p.id desc order by p.sort asc, p.id desc

mapper.update:
update mall_product
set sales = greatest(sales + #{delta}, 0), update_time = now()
where id = #{id}
